// Fast O(1) monotonic cursor-based lookup and linear interpolation on ESP32
inline bool sim_get_sample(float t_s, float &out_pressure, float &out_vert_accel, float &out_lat_accel) {
    static uint16_t sim_cursor = 0;
    if (SIM_DATA_COUNT == 0) return false;

    if (t_s <= SIM_DATA[0].time_s) {
        out_pressure   = SIM_DATA[0].pressure_pa;
        out_vert_accel = SIM_DATA[0].vert_accel;
        out_lat_accel  = SIM_DATA[0].lat_accel;
        return true;
    }

    if (t_s >= SIM_DATA[SIM_DATA_COUNT - 1].time_s) {
        out_pressure   = SIM_DATA[SIM_DATA_COUNT - 1].pressure_pa;
        out_vert_accel = SIM_DATA[SIM_DATA_COUNT - 1].vert_accel;
        out_lat_accel  = SIM_DATA[SIM_DATA_COUNT - 1].lat_accel;
        return false; // Reached end of simulation
    }

    // Advance cursor monotonically in O(1) amortized time
    while (sim_cursor + 1 < SIM_DATA_COUNT && SIM_DATA[sim_cursor + 1].time_s <= t_s) {
        sim_cursor++;
    }
    // Rewind cursor if timestamp went backwards (e.g. restart / reboot)
    while (sim_cursor > 0 && SIM_DATA[sim_cursor].time_s > t_s) {
        sim_cursor--;
    }

    const SimDataPoint &p0 = SIM_DATA[sim_cursor];
    const SimDataPoint &p1 = SIM_DATA[sim_cursor + 1];
    float dt = p1.time_s - p0.time_s;
    float factor = (dt > 1e-6f) ? ((t_s - p0.time_s) / dt) : 0.0f;
    if (factor < 0.0f) factor = 0.0f;
    if (factor > 1.0f) factor = 1.0f;

    out_pressure   = p0.pressure_pa + factor * (p1.pressure_pa - p0.pressure_pa);
    out_vert_accel = p0.vert_accel  + factor * (p1.vert_accel  - p0.vert_accel);
    out_lat_accel  = p0.lat_accel   + factor * (p1.lat_accel   - p0.lat_accel);
    return true;
}

